import numpy as np
from collections import Counter

def apply(A, mr, mc, dr, dc):
    A=A.copy(); H,W=A.shape; mcol=A[mr][mc]
    for k in range(1, max(H,W)+2):
        r0,r1=mr-k*dr, mr+k*dr; c0,c1=mc-k*dc, mc+k*dc
        if not (0<=r0<H and 0<=c0<W and 0<=r1<H and 0<=c1<W): break
        for c in range(max(0,c0), min(W-1,c1)+1):
            for rr in (r0,r1):
                if 0<=rr<H: A[rr,c]=mcol
        for r in range(max(0,r0), min(H-1,r1)+1):
            for cc in (c0,c1):
                if 0<=cc<W: A[r,cc]=mcol
    return A

