import numpy as np, json
def solve(T):
    A=np.array(T); H,W=A.shape
    cnt=Counter(A.ravel().tolist()); bgc=cnt.most_common(1)[0][0]
    pts=[(r,c) for r in range(H) for c in range(W) if A[r][c]!=bgc and cnt[A[r][c]]<=3]
    rare_c=next(c for c,_ in pts)
    pts.sort()
    (mr,mc),(nr,nc),(rr,rc)=pts[0],pts[1],pts[2]
    dr=(nr+rr)//2-mr; dc=(nc+rc)//2-mc
    out=A.copy(); k=1
    while True:
        r0=mr+k*dr; r1=mr-k*dr; c0=mc+k*dc; c1=mc-k*dc
        # stop when frame fully surrounds the grid
        if r0<0 and r1>=H-1 and c0<0 and c1>=W-1: break
        for s in (c0,c1):
            for r_ in range(max(0,r0),min(H-1,r1)+1):
                if out[r_,s]==bgc: out[r_,s]=rare_c
        for s in (r0,r1):
            for c_ in range(max(0,c0),min(W-1,c1)+1):
                if out[s,c_]==bgc: out[s,c_]=rare_c
        k+=1
        if k>100: break
    return out.tolist()
for n in [2,3,4,5,6,7,8]:
    try:
        ok=solve(G[f'Demo pair {n} input'])==G[f'Demo pair {n} output']
        print(n,ok)
    except Exception as e:
        print(n,'ERR',e)
